require"active_support/core_ext/module/attribute_accessors";require"active_support/core_ext/module/delegation";require"json";module ActiveSupport;mattr_accessor:parse_json_times;module JSON;DATE_REGEX=/\A\d{4}-\d{2}-\d{2}\z/;DATETIME_REGEX=/\A(?:\d{4}-\d{2}-\d{2}|\d{4}-\d{1,2}-\d{1,2}[T \t]+\d{1,2}:\d{2}:\d{2}(\.[0-9]*)?(([ \t]*)Z|[-+]\d{2}?(:\d{2})?)?)\z/;class <<self;def decode(json)data=::JSON.parse(json,quirks_mode:true);if ActiveSupport.parse_json_times;convert_dates_from(data);else data;end;end;alias_method:load,:decode;def parse_error;::JSON::ParserError;end;private;def convert_dates_from(data)case data;when nil;nil;when DATE_REGEX;begin Date.parse(data);rescue ArgumentError;data;end;when DATETIME_REGEX;begin Time.zone.parse(data);rescue ArgumentError;data;end;when Array;data.map!{|d|convert_dates_from(d)};when Hash;data.transform_values! do |value|convert_dates_from(value);end;else data;end;end;end;end;end
